parameters.jsCode:
// Corta la ejecución ANTES de gastar en Kie si el agente repite una especie (o su género)
// o entrega una salida inservible.
const brief = $('Preparar Brief').first().json;
const out = $input.first().json.output || {};

const norm = s => String(s || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9 ()]/g, ' ').replace(/\s+/g, ' ').trim();
const nombre = s => norm(s).replace(/\(.*?\)/g, '').trim();
const genero = s => {
  const m = String(s || '').match(/\(([^)]+)\)/);
  return m ? norm(m[1]).split(' ')[0] : null;
};

if (!out.especie || !out.referencia_visual || !out.referencia_escenario || !Array.isArray(out.storyboard) || out.storyboard.length !== 4) {
  throw new Error('El agente devolvió una salida incompleta (falta especie, referencias, o el storyboard no tiene 4 tomas).');
}

const usadas = brief.usadas === '(ninguna todavía)' ? [] : String(brief.usadas).split(' | ');
const g = genero(out.especie);
const repetida = usadas.find(u => nombre(u) === nombre(out.especie) || (g && genero(u) === g));
if (repetida) {
  throw new Error('Especie repetida: "' + out.especie + '" ya se usó ("' + repetida + '"). No se gastó nada en Kie; vuelve a ejecutar.');
}

out.storyboard.forEach((t, i) => {
  if (!t || !t.keyframe || !t.movimiento) throw new Error('La toma ' + (i + 1) + ' no tiene keyframe o movimiento.');
});

// La narración (inglés) debe caber en ~28 s de voz: la voz de Gemini habla a ~2 palabras/s.
const palabras = String(out.narracion || '').trim().split(/\s+/).filter(Boolean).length;
if (palabras < 38 || palabras > 64) {
  throw new Error('La narración tiene ' + palabras + ' palabras; debe tener entre 38 y 64 (el montaje acelera la voz hasta 1.25× para que entre en 28 s). No se gastó nada en Kie.');
}

// Nombre base común para todos los archivos del video: 2026-09-20_0900_especie
const stamp = new Date().toLocaleString('sv-SE', { hour12: false }).replace(' ', '_').replace(/:/g, '').slice(0, 15);
const slug = nombre(out.especie).replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 40) || 'video';
const base = stamp + '_' + slug;

return $input.all().map(i => ({ json: { ...i.json, base } }));

// Veo (API clásica de Kie): successFlag 0 = generando, 1 = listo, 2/3 = falló.
const d = $input.first().json.data || {};
const flag = d.successFlag;
if (flag === 2 || flag === 3) throw new Error('Veo falló: ' + (d.errorMessage || d.errorCode || 'sin detalle') + ' (taskId ' + d.taskId + ')');
if ($runIndex > 60) throw new Error('Tiempo de espera agotado. La tarea ' + d.taskId + ' sigue generando; puedes reanudar desde el nodo Consultar Toma.');
return [{ json: { ...$input.first().json, done: flag === 1 } }];

