const d = $input.first().json.data || {};
const state = d.state;
if (state === 'fail') throw new Error('Kie reportó un fallo: ' + (d.failMsg || d.failCode || 'sin detalle') + ' (taskId ' + d.taskId + ')');
if ($runIndex > 40) throw new Error('Tiempo de espera agotado. La tarea ' + d.taskId + ' sigue en estado ' + state + '; puedes reanudar desde el nodo Get.');
return [{ json: { ...$input.first().json, done: state === 'success' } }];

const v = $('Validar Nuevo').first().json;
const b64 = Buffer.from(String(v.output.narracion), 'utf8').toString('base64');
return [{ json: { base: v.base, command: 'node /opt/tools/burn.js ' + v.base + ' ' + b64 } }];

const r = $input.first().json;
let out;
try { out = JSON.parse(String(r.stdout || '').trim().split('\n').pop()); }
catch (e) { throw new Error('El montaje no devolvió una respuesta válida: ' + String(r.stderr || r.stdout || '').slice(-400)); }
if (!out.ok) throw new Error('Falló el montaje: ' + out.error);
return [{ json: out }];

// Storyboard de 4 tomas → un prompt CORTO por toma para Veo 3.1 Lite (Kie).
// Los modelos de video rinden mejor con 3-4 ideas claras: sujeto, encuadre, una acción y luz. Cada parte se recorta en frase completa.
const v = $('Validar Nuevo').first().json;
const o = v.output || {};
const sb = o.storyboard;
if (!Array.isArray(sb) || sb.length !== 4) throw new Error('Se esperaban 4 tomas en el storyboard, llegaron ' + (sb ? sb.length : 0));
const limpio = s => String(s || '').replace(/@\S+/g, m => m.replace('@', '')).replace(/\s+/g, ' ').trim();
// recorta a `max` caracteres sin partir frases
const corto = (s, max) => {
  s = limpio(s);
  if (s.length <= max) return s;
  const cut = s.slice(0, max);
  const fin = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('; '), cut.lastIndexOf(', '));
  return (fin > max * 0.5 ? cut.slice(0, fin + 1) : cut).trim();
};
const SOLIDEZ = 'One solid, opaque animal with real mass and correct anatomy; no morphing, no ghosting, no extra limbs, no text; natural ambience only.';

return sb.map((t, i) => {
  const prompt_video = [
    `Vertical 9:16 photorealistic wildlife documentary shot. ${corto(t.plano, 80)}.`,
    `Subject: ${corto(o.referencia_visual, 260)}`,
    `Frame: ${corto(t.keyframe, 320)}`,
    `Action: ${corto(t.movimiento, 260)}`,
    `Setting: ${corto(o.referencia_escenario, 220)}`,
    SOLIDEZ,
  ].join('\n');
  return { json: { base: v.base, sceneIndex: i, prompt_video } };
});

// Une las 4 tomas de Veo (8 s cada una, 720p). De cada toma se usan los primeros 7 s:
// se descarta el final del clip, que es donde suelen aparecer los errores. Resultado: 4 × 7 s = 28 s.
const base = $('Validar Nuevo').first().json.base;
const N = 4, SEG = 7;
const inputs = Array.from({ length: N }, (_, i) => `-i /files/${base}_${i}.mp4`).join(' ');
const cortes = Array.from({ length: N }, (_, i) => `[${i}:v]trim=0:${SEG},setpts=PTS-STARTPTS[v${i}]`).join(';');
const unir = Array.from({ length: N }, (_, i) => `[v${i}]`).join('') + `concat=n=${N}:v=1:a=0[outv]`;
const command = `/opt/tools/ffmpeg -y ${inputs} -filter_complex "${cortes};${unir}" -map "[outv]" -c:v libx264 -crf 18 -preset veryfast -an /files/${base}.mp4`;
return [{ json: { command, base } }];

// Caption de TikTok: título + hashtags (máx. 2200 caracteres).
const o = $('Director de Cine').first().json.output;
const base = $('Validar Nuevo').first().json.base;
const caption = [o.titulo, (o.hashtags || []).join(' ') + ' #wildlife #nature'].join('\n\n').slice(0, 2200);
const b64 = Buffer.from(caption, 'utf8').toString('base64');
return [{ json: { base, command: 'node /opt/tools/tiktok_post.js /files/final/' + base + '_final.mp4 ' + b64 } }];

const r = $input.first().json;
let out;
try { out = JSON.parse(String(r.stdout || '').trim().split('\n').pop()); }
catch (e) { throw new Error('La publicación en TikTok no devolvió una respuesta válida: ' + String(r.stderr || r.stdout || '').slice(-400)); }
if (!out.ok) throw new Error('Falló la publicación en TikTok: ' + out.error);
return [{ json: out }];
